,785,812,2329,1031,false,false,false,false,false,false,false,false,false,false,false,false,"xiamier_0"},h)g[405403]=b({e[21034],405403,13,105,283,"「ここは貸切風呂のはずなんだけど……いや、僕が勘違いしていたのかもしれない。お騒がせしたお詫びに後で何か奢らせて。この温泉のたこ焼きは種類が豊富なことで有名でね。君好みのたこ焼きもあると思うんだ。」",200054,2,"deco/character/xiamier_WQ",false,false,false,false,false,false,false,false,false,false,false,"0,312,1",1835,885,444,835,169,2614,2525,835,606,2614,false,false,false,false,false,false,false,false,false,false,false,false,false,"xiamier_wq"},h)g[405404]=b({e[45057],405404,12,131,284,"「はは……今まで何度も盛大な祝祭に参加してきたけど、今日のこのプライベートな場ほど緊張したことはないよ。僕の心の音楽、聴いてくれるかい？」",200054,2,"deco/character/xiamier_LF",false,false,1,false,false,false,false,"1",false,false,"-420,0,1","150,0,0.98","-420,0,1","-420,0,1","-80,0,1",false,false,false,false,false,false,false,false,false,false,false,2284,856,420,516,198,2773,2998,516,565,2773,"xiamier_lf"},h)g[405405]=b({e[17044],405405,18,65,285,"「ずっと寝返りを打ってるけど、もしかして眠れない？　それなら、星座にまつわる話をしてあげようか。\n……大変？　ぜーんぜん、そんなことないよ。むしろ、君のためなら喜んで話すとも。\nそうだね、まずは君の星座の話からしようか。それは遠い、遠い昔のこと……。」",200054,2,"deco/character/xiamier_xl",false,false,false,false,false,false,false,"1",0,false,false,false,false,false,false,false,false,false,false,false,false,"xiamier_xl"},h)g[405501]=b({e[25034],405501,false,132,286,false,200055,false,"deco/character/sigonghuiye",302002,60,false,false,false,false,-135,"1.10000002384186",false,false,false,false,false,false,false,"50,50,1.05",1833,855,385,1540,797,877,2436,1540,797,877,1011},h)g[405502]=b({e[11034],405502,1,110,287,false,200055,1,"deco/character/sigonghuiye_0",302002,60,1952,882,374,922,173,2319,3128,922,568,2319},h)g[405503]=b({e[23034],405503,999,133,288,false,200055,3,"deco/character/sigonghuiye_phantom",false,false,false,false,false,false,false,false,false,"0,130,1","0,140,1",false,"0,160,1","0,150,1",1871,1006,361,663,false,2664,3144,663,686,2664},h)g[405601]=b({e[25034],405601,false,134,289,false,200056,false,"deco/character/baiyinyuxing",302002,60,false,false,false,false,-19,"1